{
  "name": "Autolab电化学工作站",
  "name_en": "Autolab Electrochemical Workstation",
  "manufacturer": "Metrohm Autolab",
  "description": "Autolab电化学工作站是一类用于电化学实验的恒电位/恒电流测试仪器，可控制电化学池的电位与电流并采集响应信号。它常用于循环伏安、计时电流/计时电位、电化学阻抗谱（FRA/EIS）以及电池、腐蚀、传感器和电催化等研究。",
  "description_en": "The Autolab electrochemical workstation is a potentiostat/galvanostat for electrochemical experiments. It controls the potential or current of an electrochemical cell and records the response signal. It is commonly used for cyclic voltammetry, chrono methods, electrochemical impedance spectroscopy (FRA/EIS), and studies of batteries, corrosion, sensors, and electrocatalysis.",
  "tag_hints": [
    "electrochemical workstation",
    "potentiostat galvanostat",
    "electrochemical impedance spectroscopy",
    "FRA",
    "voltammetry",
    "battery testing",
    "corrosion analysis"
  ],
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接电化学工作站。",
      "description_en": "Connect to the electrochemical workstation."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与电化学工作站的连接。",
      "description_en": "Disconnect from the electrochemical workstation."
    },
    {
      "action_name": "auto-ismeasuring",
      "description": "查询仪器是否正在进行测量。",
      "description_en": "Check whether the instrument is currently measuring."
    },
    {
      "action_name": "auto-potential",
      "description": "读取当前电极电位。",
      "description_en": "Read the current electrode potential."
    },
    {
      "action_name": "auto-current",
      "description": "读取当前电流。",
      "description_en": "Read the current."
    },
    {
      "action_name": "auto-setCurrentRange",
      "description": "设置电流量程。",
      "description_en": "Set the current range."
    },
    {
      "action_name": "auto-setStability",
      "description": "设置控制稳定性参数。",
      "description_en": "Set the control stability parameter."
    },
    {
      "action_name": "auto-appliedPotential",
      "description": "读取当前施加的电位。",
      "description_en": "Read the currently applied potential."
    },
    {
      "action_name": "auto-abort",
      "description": "中止当前测量。",
      "description_en": "Abort the current measurement."
    },
    {
      "action_name": "auto-loadProcedure",
      "description": "加载测量流程或实验方法。",
      "description_en": "Load a measurement procedure or experimental method."
    },
    {
      "action_name": "auto-setSetpoints",
      "description": "设置测量流程中的参数设定值。",
      "description_en": "Set parameter setpoints for the measurement procedure."
    },
    {
      "action_name": "auto-whileMeasuring",
      "description": "在测量过程中持续读取指定类型的数据。",
      "description_en": "Continuously read a specified type of data during measurement."
    },
    {
      "action_name": "auto-CellOnOff",
      "description": "打开或关闭电化学池输出。",
      "description_en": "Turn the electrochemical cell output on or off."
    },
    {
      "action_name": "auto-parseNox",
      "description": "解析Autolab实验方法文件（.nox）。",
      "description_en": "Parse an Autolab procedure file (.nox)."
    },
    {
      "action_name": "auto-parseFRA",
      "description": "解析频率响应分析测量数据。",
      "description_en": "Parse frequency response analyzer measurement data."
    },
    {
      "action_name": "auto-performMeasurement",
      "description": "按指定流程执行一次完整测量，并可设置参数、控制电池开关及保存数据。",
      "description_en": "Run a complete measurement with a specified procedure, including setpoints, cell control, and data saving."
    }
  ]
}

